;(function(){
 var KEY='quanta-pomo-pos', drag=null;
 function node(){return document.querySelector('.pomodoro');}
 function clamp(x,y,n){var w=n.offsetWidth,h=n.offsetHeight;
   return {x:Math.min(Math.max(6,x),Math.max(6,window.innerWidth-w-6)),
           y:Math.min(Math.max(6,y),Math.max(6,window.innerHeight-h-6))};}
 function place(n,x,y){n.style.left=x+'px';n.style.top=y+'px';n.style.right='auto';n.style.bottom='auto';}
 document.addEventListener('pointerdown',function(e){
   if(!e.target.closest)return;
   var n=e.target.closest('.pomodoro');
   if(!n||e.target.closest('button'))return;
   var r=n.getBoundingClientRect();
   drag={n:n,dx:e.clientX-r.left,dy:e.clientY-r.top,moved:false};
   n.classList.add('dragging');
   try{n.setPointerCapture(e.pointerId);}catch(_){}
 });
 document.addEventListener('pointermove',function(e){
   if(!drag)return;
   var p=clamp(e.clientX-drag.dx,e.clientY-drag.dy,drag.n);
   place(drag.n,p.x,p.y);drag.moved=true;e.preventDefault();
 },{passive:false});
 function end(){
   if(!drag)return;
   drag.n.classList.remove('dragging');
   if(drag.moved){try{localStorage.setItem(KEY,JSON.stringify({x:parseInt(drag.n.style.left,10),y:parseInt(drag.n.style.top,10)}));}catch(_){}}
   drag=null;
 }
 document.addEventListener('pointerup',end);
 document.addEventListener('pointercancel',end);
 var tries=0, iv=setInterval(function(){
   var n=node();
   if(++tries>60){clearInterval(iv);return;}
   if(!n)return;
   clearInterval(iv);
   n.title='Arraste para mover';
   try{var s=localStorage.getItem(KEY);if(s){var p=JSON.parse(s),c=clamp(p.x,p.y,n);place(n,c.x,c.y);}}catch(_){}
 },150);
 window.addEventListener('resize',function(){
   var n=node();if(!n||!n.style.left)return;
   var c=clamp(parseInt(n.style.left,10),parseInt(n.style.top,10),n);place(n,c.x,c.y);
 });
})();
